        rtr_order_value_band__standard.effective_tax_rate3 as effective_tax_rate,
        rtr_order_value_band__standard.food_item_lines3 as food_item_lines,
        rtr_order_value_band__standard.drink_item_lines3 as drink_item_lines,
        rtr_order_value_band__standard.food_share_of_lines3 as food_share_of_lines,
        rtr_order_value_band__standard.drink_share_of_lines3 as drink_share_of_lines,
        'STANDARD' as order_value_band,
        rtr_order_value_band__standard.customer_order_number3 as customer_order_number
    from rtr_order_value_band__standard
),

-- UN_ORDER_BANDS · Union · L1861–1978
un_order_bands as (
    -- group EXP_HIGH_BAND
    select
        exp_high_band.order_id,
        exp_high_band.customer_id,
        exp_high_band.ordered_at_day,
        exp_high_band.order_subtotal,
        exp_high_band.order_tax_paid,
        exp_high_band.order_total,
        exp_high_band.order_cogs,
        exp_high_band.order_gross_profit,
        exp_high_band.order_gross_margin_pct,
        exp_high_band.order_value_band
    from exp_high_band
    union all
    -- group EXP_STD_BAND
    select
        exp_std_band.order_id,
        exp_std_band.customer_id,
        exp_std_band.ordered_at_day,
        exp_std_band.order_subtotal,
        exp_std_band.order_tax_paid,
        exp_std_band.order_total,
        exp_std_band.order_cogs,
        exp_std_band.order_gross_profit,
        exp_std_band.order_gross_margin_pct,
        exp_std_band.order_value_band
    from exp_std_band
),

-- AGGTRANS · Aggregator · L2185–2211
aggtrans as (
    select
        un_order_bands.customer_id,
        count(un_order_bands.order_id) as count_lifetime_orders,
        min(un_order_bands.ordered_at_day) as first_ordered_at,
        max(un_order_bands.ordered_at_day) as last_ordered_at,
        sum(un_order_bands.order_total) as lifetime_spend,
        sum(un_order_bands.order_subtotal) as lifetime_spend_pretax,
        sum(un_order_bands.order_tax_paid) as lifetime_tax_paid,
        sum(un_order_bands.order_cogs) as lifetime_cogs,
        sum(un_order_bands.order_gross_profit) as lifetime_gross_profit,
        sum(case when un_order_bands.order_value_band = 'HIGH' then 1 else 0 end) as high_value_orders
    from un_order_bands
    group by un_order_bands.customer_id
),

-- SQ_STG_CUSTOMERS1 · Source Qualifier · L2212–2226 · reads STG_CUSTOMERS (L1056–1059), which another mapping writes: ref() (decision Q5)
sq_stg_customers1 as (
    select
        stg_customers.customer_id,
        stg_customers.customer_name
    from {{ ref('stg_customers') }} as stg_customers
),

-- JNR_CUSTOMERS · Joiner · L2227–2252 · Master Outer Join
jnr_customers as (
    select
        detail.customer_id,
        detail.count_lifetime_orders,
        detail.first_ordered_at,
        detail.last_ordered_at,
        detail.lifetime_spend,
        detail.lifetime_spend_pretax,
        detail.lifetime_tax_paid,
        detail.lifetime_cogs,
        detail.lifetime_gross_profit,
        detail.high_value_orders,
        master.customer_name
    from aggtrans as detail
    left join sq_stg_customers1 as master  -- FLAG master_outer L2243: JNR_CUSTOMERS is a Master Outer Join: it keeps every row from AGGTRANS (detail) and only the rows from SQ_STG_CUSTOMERS1 (master) that match; SQ_STG_CUSTOMERS1 rows with no match are dropped
        on master.customer_id = detail.customer_id
),

-- EXP_CUSTOMER_METRICS · Expression · L2253–2284
exp_customer_metrics as (
    select
        jnr_customers.customer_id,
        jnr_customers.customer_name,
        jnr_customers.count_lifetime_orders,
        jnr_customers.first_ordered_at,
        jnr_customers.last_ordered_at,
        /* v_SPEND_CL L2268 */ (case when (jnr_customers.lifetime_spend is null) then 0 else jnr_customers.lifetime_spend end) as lifetime_spend,
        /* v_SPEND_PRETAX_CL L2269 */ (case when (jnr_customers.lifetime_spend_pretax is null) then 0 else jnr_customers.lifetime_spend_pretax end) as lifetime_spend_pretax,
        /* v_TAX_CL L2270 */ (case when (jnr_customers.lifetime_tax_paid is null) then 0 else jnr_customers.lifetime_tax_paid end) as lifetime_tax_paid,
        /* v_COGS_CL L2271 */ (case when (jnr_customers.lifetime_cogs is null) then 0 else jnr_customers.lifetime_cogs end) as lifetime_cogs,
        /* v_PROFIT_CL L2272 */ (case when (jnr_customers.lifetime_gross_profit is null) then 0 else jnr_customers.lifetime_gross_profit end) as lifetime_gross_profit,
        case when /* v_ORDERS_CL L2267 */ (case when (jnr_customers.count_lifetime_orders is null) then 0 else jnr_customers.count_lifetime_orders end) = 0 then 0 else /* v_SPEND_CL L2268 */ (case when (jnr_customers.lifetime_spend is null) then 0 else jnr_customers.lifetime_spend end) / /* v_ORDERS_CL L2267 */ (case when (jnr_customers.count_lifetime_orders is null) then 0 else jnr_customers.count_lifetime_orders end) end as avg_order_value,
        /* v_HIGH_VALUE_CL L2273 */ (case when (jnr_customers.high_value_orders is null) then 0 else jnr_customers.high_value_orders end) as high_value_orders,
        case when /* v_ORDERS_CL L2267 */ (case when (jnr_customers.count_lifetime_orders is null) then 0 else jnr_customers.count_lifetime_orders end) > 1 then 'returning' else 'new' end as customer_type
    from jnr_customers
),

-- EXP_RECENCY1 · Expression · L2285–2302
exp_recency1 as (
    select
        exp_customer_metrics.customer_id,
        exp_customer_metrics.customer_name,
        exp_customer_metrics.count_lifetime_orders,
        exp_customer_metrics.first_ordered_at,
        exp_customer_metrics.last_ordered_at,
        exp_customer_metrics.lifetime_spend,
        exp_customer_metrics.lifetime_spend_pretax,
        exp_customer_metrics.lifetime_tax_paid,
        exp_customer_metrics.lifetime_cogs,
        exp_customer_metrics.lifetime_gross_profit,
        exp_customer_metrics.avg_order_value,
        exp_customer_metrics.high_value_orders,
        exp_customer_metrics.customer_type,
        /* v_RECENCY_DAYS L2300 */ (case when (exp_customer_metrics.last_ordered_at is null) then 9999 else ((epoch(date_trunc('day', /* $$RUN_DATE L3104 */ cast('{{ var('run_date', '2025-12-31') }}' as timestamp))) - epoch(date_trunc('day', exp_customer_metrics.last_ordered_at))) / 86400) end) as recency_days_temp
    from exp_customer_metrics
),

-- EXP_RECENCY2 · Expression · L2303–2321
exp_recency2 as (
    select
        exp_recency1.customer_id,
        exp_recency1.customer_name,
        exp_recency1.count_lifetime_orders,
        exp_recency1.first_ordered_at,
        exp_recency1.last_ordered_at,
        exp_recency1.lifetime_spend,
        exp_recency1.lifetime_spend_pretax,
        exp_recency1.lifetime_tax_paid,
        exp_recency1.lifetime_cogs,
        exp_recency1.lifetime_gross_profit,
        exp_recency1.avg_order_value,
        exp_recency1.high_value_orders,
        exp_recency1.customer_type,
        /* v_RECENCY_FINAL L2318 */ (case when (exp_recency1.last_ordered_at is null) then 9999 else ((epoch(date_trunc('day', /* $$RUN_DATE L3104 */ cast('{{ var('run_date', '2025-12-31') }}' as timestamp))) - epoch(date_trunc('day', exp_recency1.last_ordered_at))) / 86400) end) as recency_days
    from exp_recency1
),

-- EXP_RFM_SCORES · Expression · L2322–2345
exp_rfm_scores as (
    select
        exp_recency2.customer_id,
        exp_recency2.customer_name,
        exp_recency2.count_lifetime_orders,
        exp_recency2.first_ordered_at,
        exp_recency2.last_ordered_at,
        exp_recency2.lifetime_spend,
        exp_recency2.lifetime_spend_pretax,
        exp_recency2.lifetime_tax_paid,
        exp_recency2.lifetime_cogs,
        exp_recency2.lifetime_gross_profit,
        exp_recency2.avg_order_value,
        exp_recency2.high_value_orders,
        exp_recency2.customer_type,
        exp_recency2.recency_days,
        /* v_R_SCORE L2341 */ (case when exp_recency2.recency_days <= 30 then 3 else case when exp_recency2.recency_days <= 90 then 2 else 1 end end) as r_score,
        /* v_F_SCORE L2342 */ (case when exp_recency2.count_lifetime_orders >= 5 then 3 else case when exp_recency2.count_lifetime_orders >= 2 then 2 else 1 end end) as f_score,
        /* v_M_SCORE L2343 */ (case when exp_recency2.lifetime_spend >= 200 then 3 else case when exp_recency2.lifetime_spend >= 50 then 2 else 1 end end) as m_score,
        (/* v_R_SCORE L2341 */ (case when exp_recency2.recency_days <= 30 then 3 else case when exp_recency2.recency_days <= 90 then 2 else 1 end end) * 100) + (/* v_F_SCORE L2342 */ (case when exp_recency2.count_lifetime_orders >= 5 then 3 else case when exp_recency2.count_lifetime_orders >= 2 then 2 else 1 end end) * 10) + /* v_M_SCORE L2343 */ (case when exp_recency2.lifetime_spend >= 200 then 3 else case when exp_recency2.lifetime_spend >= 50 then 2 else 1 end end) as rfm_score
    from exp_recency2
),

-- EXP_RFM_SEGMENT · Expression · L2346–2368
exp_rfm_segment as (
    select
        exp_rfm_scores.customer_id,
        exp_rfm_scores.customer_name,
        exp_rfm_scores.count_lifetime_orders,
        exp_rfm_scores.first_ordered_at,
        exp_rfm_scores.last_ordered_at,
        exp_rfm_scores.lifetime_spend,
        exp_rfm_scores.lifetime_spend_pretax,
        exp_rfm_scores.lifetime_tax_paid,
        exp_rfm_scores.lifetime_cogs,
        exp_rfm_scores.lifetime_gross_profit,
        exp_rfm_scores.avg_order_value,
        exp_rfm_scores.high_value_orders,
        exp_rfm_scores.customer_type,
        exp_rfm_scores.recency_days,
        exp_rfm_scores.r_score,
        exp_rfm_scores.f_score,
        exp_rfm_scores.m_score,
        exp_rfm_scores.rfm_score,
        /* v_SEGMENT L2366 */ (case when exp_rfm_scores.count_lifetime_orders = 0 then 'PROSPECT' else case when exp_rfm_scores.rfm_score = 333 then 'CHAMPION' else case when ((exp_rfm_scores.r_score = 3 and exp_rfm_scores.f_score >= 2) and exp_rfm_scores.m_score >= 2) then 'LOYAL' else case when (exp_rfm_scores.r_score = 1 and exp_rfm_scores.f_score >= 2) then 'AT_RISK' else 'STANDARD' end end end end) as rfm_segment
    from exp_rfm_scores
)

select
    cast(exp_rfm_segment.customer_id as varchar) as customer_id,
    cast(exp_rfm_segment.customer_name as varchar) as customer_name,
    cast(exp_rfm_segment.count_lifetime_orders as decimal(15,0)) as count_lifetime_orders,
    cast(exp_rfm_segment.first_ordered_at as timestamp) as first_ordered_at,
    cast(exp_rfm_segment.last_ordered_at as timestamp) as last_ordered_at,
    cast(exp_rfm_segment.lifetime_spend as decimal(12,2)) as lifetime_spend_pretax,  -- FLAG crossed L2480: EXP_RFM_SEGMENT.LIFETIME_SPEND goes into CUSTOMER_360.LIFETIME_SPEND_PRETAX, as the connector says
    cast(exp_rfm_segment.lifetime_spend_pretax as decimal(12,2)) as lifetime_tax_paid,  -- FLAG crossed L2481: EXP_RFM_SEGMENT.LIFETIME_SPEND_PRETAX goes into CUSTOMER_360.LIFETIME_TAX_PAID, as the connector says
    cast(exp_rfm_segment.lifetime_tax_paid as decimal(12,2)) as lifetime_spend,  -- FLAG crossed L2482: EXP_RFM_SEGMENT.LIFETIME_TAX_PAID goes into CUSTOMER_360.LIFETIME_SPEND, as the connector says
    cast(exp_rfm_segment.lifetime_cogs as decimal(12,2)) as lifetime_cogs,
    cast(exp_rfm_segment.lifetime_gross_profit as decimal(12,2)) as lifetime_gross_profit,
    cast(exp_rfm_segment.avg_order_value as decimal(12,2)) as avg_order_value,  -- FLAG rounds L2485: AVG_ORDER_VALUE is computed as IIF(v_ORDERS_CL=0,0,v_SPEND_CL/v_ORDERS_CL) (L2264), a double at run time because high precision is off, and is rounded to 2 decimal places by the target column AVG_ORDER_VALUE decimal(12,2) (decision Q11)
    cast(exp_rfm_segment.high_value_orders as decimal(15,0)) as high_value_orders,
    cast(exp_rfm_segment.customer_type as varchar) as customer_type,
    cast(exp_rfm_segment.recency_days as decimal(15,0)) as recency_days,
    cast(exp_rfm_segment.r_score as decimal(1,0)) as r_score,
    cast(exp_rfm_segment.f_score as decimal(1,0)) as f_score,
    cast(exp_rfm_segment.m_score as decimal(1,0)) as m_score,
    cast(exp_rfm_segment.rfm_score as decimal(15,0)) as rfm_score,
    cast(exp_rfm_segment.rfm_segment as varchar) as rfm_segment
from exp_rfm_segment
